def regex(self, text):
        for k in self.rules.keys():
            m = re.match("^"+k+"$", text)
            if m:
                return k
        return ""

def priority(self, text):
        for k in self.rules.keys():
            m = re.match("^"+k+"$", text)
            if m:
                return self.rules[k][0]
        return False
